messages.content:
Run 'meta-analysis.R' using Rscript.
Questions:
{
  "q1": "fig Report N psychosis for Wium-Anderson et al, 2014 for the analysis adjusted for only age, sex, and BMI and CRP measured in adulthood/old age."
}

arguments.command:
cd /code && Rscript - <<'RS'
files <- c('/data/less3more3.csv','/data/per-sd.csv','/data/multi-level.csv')
for (f in files) {
  d <- read.csv(f, stringsAsFactors=FALSE)
  cat('\nFILE', f, '\n')
  cat('cols:', paste(names(d), collapse=', '), '\n')
  idx <- grepl('Wium', paste(d, collapse=' '), ignore.case=TRUE)
  if (any(idx)) {
    print(d[idx, intersect(names(d), c('Authoryear','Author','Year','N','N-outcome','N_nohi','N_outcomes_nohi','age_psychiatric_outcome','age','CRP_categories'))])
  } else {
    cat('No Wium rows found\n')
  }
}
RS
